      b.fillStyle = '#ece8dd'; b.fillRect(P.x + 40, P.y + 40, 330, 50); b.strokeRect(P.x + 40, P.y + 40, 330, 50);
      b.font = '400 24px "Special Elite"'; b.fillStyle = '#4b453c'; b.textAlign = 'left'; b.fillText('RIVERSIDE — CITY MAP', P.x + 56, P.y + 74);
