      for (let i = 0; i < d.length; i += 4) { const v = (d[i] * .3 + d[i + 1] * .59 + d[i + 2] * .11) + (R() - .5) * 34; d[i] = v * 1.08; d[i + 1] = v * 1.0; d[i + 2] = v * .88; }
