      s.lineWidth = 4; s.beginPath(); s.roundRect(34, 34, 692, 172, 10); s.stroke();
      s.font = '400 150px Anton'; s.textAlign = 'center'; s.textBaseline = 'middle'; if ('letterSpacing' in s) s.letterSpacing = '14px'; s.fillText('UNSOLVED', 386, 126);
      s.globalCompositeOperation = 'destination-out';
