      for (let i = 0; i < 14; i++) { s.globalAlpha = .5; s.lineWidth = 1 + R() * 3; s.beginPath(); const y = R() * 240; s.moveTo(R() * 300, y); s.lineTo(300 + R() * 460, y + (R() - .5) * 20); s.stroke(); }
