      const w = 230, h = 268, k = E.out(u);
      g.save(); g.translate(x + w / 2, y + h / 2 - (1 - k) * 30); g.rotate(r + (1 - k) * .1); g.globalAlpha = Math.min(1, u * 2);
      g.shadowColor = 'rgba(0,0,0,.55)'; g.shadowBlur = 22 - 8 * k; g.shadowOffsetY = 10 + 10 * (1 - k); g.fillStyle = '#f2efe6'; g.fillRect(-w / 2, -h / 2, w, h); g.shadowColor = 'transparent';
