      cy: K.track([[0, 560], [1.0, 560], [2.0, 470], [3.0, 480], [4.8, 540], [6.2, LOC.bridge[1] + 30], [7.6, 600], [10, 570, 'inOutSine']], t),
      z: K.track([[0, .9], [1.0, .92], [2.0, 1.02], [3.0, 1.05], [4.8, .98], [6.2, 1.55], [7.6, 1.1], [10, 1.2, 'inOutSine']], t),
