        g.strokeStyle = '#a40f18'; g.lineWidth = 3; g.beginPath(); g.moveTo(-52, 38); g.quadraticCurveTo(0, 46, 54, 36); g.stroke();
        g.restore(); pin(x + 85, y + 8, prog(t, 5.3, 5.45), '#e0b318');
