  man: { t0: .33, dt: .115, txt: 'Manhattan,' },      // one letter per step
  ny: { t0: 1.55, dt: .16, txt: 'New York' },
  // block fill front: [world y, time] measured from the reference (fast at the top, slower toward the tip)
  front: [[-420, 1.69], [-33, 1.96], [226, 2.22], [416, 2.47], [594, 2.72], [813, 2.98], [1000, 3.22]], jitter: .07,
  parks: [3.0, 3.25], medium: [3.2, 3.7],
